pub(crate) fn a_sequence_that_is_used_up(ty: &Ty) -> bool {
    match ty {
        Ty::Seq { shape, .. } => !shape.replays,
        _ => false,
    }
}

pub(crate) fn an_item_text(ty: &Ty) -> String {
    match ty {
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); item.text() },
        _ => if the_command_line(ty) { String::from("String") } else { String::from("?") },
    }
}

pub(crate) fn a_copy_said(path: &str, ty: &Ty) -> String {
    if ty.text().ends_with('?') { return format!("{}?.clone()", path); }
    format!("{}.clone()", path)
}

pub(crate) fn a_root_segment(path: &str) -> String {
    let parts: Vec<&str> = path.split('.').collect::<Vec<_>>();
    let first: Vec<&str> = (*nikaia_std::index::get(&parts, 0)).split('[').collect::<Vec<_>>();
    nikaia_std::block::Text::from((*nikaia_std::index::get(&first, 0)).to_string())
}

